from dataclasses import dataclass, field

@dataclass
class Dropdown:
	offset: int
	opts: list[str]

@dataclass
class KnobInfo:
	id: int
	name: str
	dropdown_id: int
	range_id: int

@dataclass
class ModInfo:
	id: int
	name: str
	img_idx: int
	knobs: dict[int, KnobInfo]
	tempo: list[KnobInfo]
	defs: list[bytes]

@dataclass
class AmpModInfo(ModInfo):
	def_cab: int
	def_mic: int

